package io.knowledgebrain.activity;
import java.util.*;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.junit.jupiter.api.Assertions.*;
class ActivityRecoveryTest extends ActivityFixtures {
 @Test void bothOwnerScansMustCompleteBeforeSeededAndFailuresRemainRecoverable(){var learning=mock(ActivitySnapshot.class);var planning=mock(ActivitySnapshot.class);var store=mock(ActivityStore.class);var space=id();var a=id();var b=id();when(learning.page(null,null)).thenReturn(new ActivitySnapshot.Page(a,null,List.of(new ActivitySnapshot.Item(a,ActivityEvent.TOPICS.get("ROADMAP"),Base64.getEncoder().encodeToString(wire("ROADMAP",space,a,id(),1,1))))));when(planning.page(null,null)).thenThrow(new IllegalStateException("controlled owner outage"));assertThrows(IllegalStateException.class,()->ActivitySnapshot.backfill(store,List.of(learning,planning)));verify(store).backfillStarted();verify(store,never()).seeded();verify(store).stage(eq("learning.roadmap.v1"),any());reset(store,planning);when(planning.page(null,null)).thenReturn(new ActivitySnapshot.Page(b,null,List.of(new ActivitySnapshot.Item(b,ActivityEvent.TOPICS.get("TASK"),Base64.getEncoder().encodeToString(wire("TASK",space,b,id(),1,1))))));ActivitySnapshot.backfill(store,List.of(learning,planning));var order=inOrder(store);order.verify(store).backfillStarted();order.verify(store).stage(eq("learning.roadmap.v1"),any());order.verify(store).stage(eq("planning.task.v1"),any());order.verify(store).seeded();}
 @Test void contentFailureKeepsAllOwnerRecoveryUnseededUntilRetryCompletes(){var learning=mock(ActivitySnapshot.class);var planning=mock(ActivitySnapshot.class);var content=mock(ActivitySnapshot.class);var store=mock(ActivityStore.class);var empty=new ActivitySnapshot.Page(null,null,List.of());when(learning.page(null,null)).thenReturn(empty);when(planning.page(null,null)).thenReturn(empty);when(content.page(null,null)).thenThrow(new IllegalStateException("Content unavailable"));assertThrows(IllegalStateException.class,()->ActivitySnapshot.backfill(store,List.of(learning,planning,content)));verify(store,never()).seeded();var id=id();doReturn(new ActivitySnapshot.Page(id,null,List.of(new ActivitySnapshot.Item(id,ActivityEvent.TOPICS.get("QUESTION"),Base64.getEncoder().encodeToString(wire("QUESTION",id(),id,id(),1,1)))))).when(content).page(null,null);ActivitySnapshot.backfill(store,List.of(learning,planning,content));verify(store).stage(eq("content.question.v1"),any());verify(store).seeded();}

 @Test void knowledgeFailureCannotMarkFourOwnerBackfillComplete(){var sources=new ArrayList<ActivitySnapshot>();for(int i=0;i<4;i++){var source=mock(ActivitySnapshot.class);when(source.page(null,null)).thenReturn(new ActivitySnapshot.Page(null,null,List.of()));sources.add(source);}var knowledge=sources.getLast();var store=mock(ActivityStore.class);when(knowledge.page(null,null)).thenThrow(new IllegalStateException("Knowledge unavailable"));assertThrows(IllegalStateException.class,()->ActivitySnapshot.backfill(store,sources));verify(store,never()).seeded();var id=id();doReturn(new ActivitySnapshot.Page(id,null,List.of(new ActivitySnapshot.Item(id,"knowledge.claim.v2",Base64.getEncoder().encodeToString(wire("CLAIM",id(),id,id(),1,1)))))).when(knowledge).page(null,null);ActivitySnapshot.backfill(store,sources);verify(store).stage(eq("knowledge.claim.v2"),any());verify(store).seeded();}

 @Test void completedDurableBackfillCommitsCapturedOffsetsIncludingEmptyLegacyTopics(){var client=mock(org.apache.kafka.clients.consumer.Consumer.class);var tail=new org.apache.kafka.common.TopicPartition("knowledge.claim.v2",0);var legacy=new org.apache.kafka.common.TopicPartition("knowledge.claim.v1",0);var backfill=mock(Runnable.class);ActivityConsumer.recover(client,List.of(tail,legacy),Map.of(tail,120L,legacy,0L),backfill);var order=inOrder(backfill,client);order.verify(backfill).run();order.verify(client).seek(tail,120L);order.verify(client).seek(legacy,0L);order.verify(client).commitSync(Map.of(tail,new org.apache.kafka.clients.consumer.OffsetAndMetadata(120L),legacy,new org.apache.kafka.clients.consumer.OffsetAndMetadata(0L)));verifyNoMoreInteractions(client);}
 @Test void incompleteBackfillNeverSeeksOrAcknowledgesAnyCapturedTail(){var client=mock(org.apache.kafka.clients.consumer.Consumer.class);var p=new org.apache.kafka.common.TopicPartition("knowledge.claim.v2",0);assertThrows(IllegalStateException.class,()->ActivityConsumer.recover(client,List.of(p),Map.of(p,120L),()->{throw new IllegalStateException("Knowledge unavailable");}));verifyNoInteractions(client);}
 @Test void configurablePollBudgetIsBoundedForMeasuredCanonicalRecovery(){var p=new Properties();ActivityConfiguration.pollInterval(p,1800000);assertEquals("1800000",p.getProperty("max.poll.interval.ms"));for(int invalid:List.of(0,599999,3600001))assertThrows(IllegalArgumentException.class,()->ActivityConfiguration.pollInterval(p,invalid));}
}
